import React, { useState } from 'react';
import axios from 'axios';

const App = () => {
  const [resorts, setResorts] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedResort, setSelectedResort] = useState(null);
  const [details, setDetails] = useState(null);

  const fetchResorts = async () => {
    try {
      const response = await axios.get('http://localhost:3001/api/ski-resorts');
      setResorts(response.data);
    } catch (error) {
      console.error('Error fetching resorts:', error);
    }
  };

  const fetchResortDetails = async (slug) => {
    try {
      const response = await axios.get(`http://localhost:3001/api/ski-resorts/${slug}`);
      setDetails(response.data);
    } catch (error) {
      console.error('Error fetching resort details:', error);
    }
  };

  const handleSearch = () => {
    fetchResorts();
  };

  const handleResortClick = (resort) => {
    setSelectedResort(resort);
    fetchResortDetails(resort.slug);
  };

  // Filter for New England resorts
  const newEnglandRegions = ["NH", "VT", "ME", "MA", "CT"];
  const filteredResorts = resorts
    .filter(resort => newEnglandRegions.includes(resort.region))
    .filter(resort => resort.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div>
      <h1>Ski Resorts</h1>
      <input 
        type="text" 
        value={searchTerm} 
        onChange={(e) => setSearchTerm(e.target.value)} 
        placeholder="Search resorts" 
      />
      <button onClick={handleSearch}>Search</button>
      <ul>
        {filteredResorts.map(resort => (
          <li key={resort.slug} onClick={() => handleResortClick(resort)}>
            {resort.name}
          </li>
        ))}
      </ul>

      {selectedResort && details && (
        <div>
          <h2>{details.resort.name}</h2>
          <h3>Lift Status</h3>
          <pre>{JSON.stringify(details.liftStatus, null, 2)}</pre>
          <h3>Weather</h3>
          <pre>{JSON.stringify(details.weather, null, 2)}</pre>
          <h3>Snow Conditions</h3>
          <pre>{JSON.stringify(details.snowConditions, null, 2)}</pre>
        </div>
      )}
    </div>
  );
};

export default App;
